<template>
  <vx-card class="servicios-filtros-card" no-radius title="Filtros de selección" :collapse-action="false">
    <template slot="actions"><button type="button" class="sf-reporte" :disabled="reporteDeshabilitado" @click="$emit('reporte')"><feather-icon icon="FileTextIcon" />Reporte del listado<feather-icon icon="ArrowUpRightIcon" /></button><button class="sf-limpiar" type="button" @click="limpiar"><feather-icon icon="RefreshCwIcon" />Limpiar filtros</button></template>
    <div class="sf-campos">
      <div><label for="sf-numero">Núm. Servicio</label><input id="sf-numero" v-model="f.numero" inputmode="numeric" maxlength="12" placeholder="Número de servicio" /></div>
      <div><label for="sf-fallecido">Nombre del fallecido</label><input id="sf-fallecido" v-model="f.fallecido" maxlength="100" placeholder="Buscar por nombre" /></div>
      <div><label for="sf-cliente">Cliente / contratante temporal</label><input id="sf-cliente" v-model="f.cliente" maxlength="100" placeholder="Nombre de quien contrató o solicitó" /></div>
      <div v-for="d in fechas" :key="d.key"><label :for="'sf-'+d.key">{{ d.label }}</label><div class="sf-fecha"><flat-pickr :id="'sf-'+d.key" v-model="f[d.key]" :config="calendario" placeholder="Selecciona una fecha" /><button v-if="f[d.key]" type="button" :aria-label="'Limpiar '+d.label" @mousedown.prevent @click.stop="f[d.key]=''"><feather-icon icon="XIcon" /></button></div></div>
    </div>
    <div class="sf-botones">
      <details class="sf-grupo"><summary><feather-icon icon="FilterIcon" />Estado <span v-if="f.estado !== ''" class="sf-num">1</span><feather-icon icon="ChevronDownIcon" /></summary><div class="sf-menu"><label v-for="o in estados" :key="o.value"><input type="radio" name="sf-estado" :value="o.value" v-model="f.estado" />{{ o.label }}</label></div></details>
      <details v-for="grupo in grupos" :key="grupo.key" class="sf-grupo"><summary><feather-icon :icon="grupo.icon" />{{ grupo.label }}<span v-if="f[grupo.key].length" class="sf-num">{{ f[grupo.key].length }}</span><feather-icon icon="ChevronDownIcon" /></summary><div class="sf-menu"><label v-for="o in grupo.options" :key="o.value"><input type="checkbox" :value="o.value" v-model="f[grupo.key]" />{{ o.label }}</label><div v-if="grupo.key === 'destinos'" class="sf-coincidencia"><label>Coincidencia de servicios</label><select v-model="f.coincidencia"><option value="todos">Todos los seleccionados</option><option value="cualquiera">Al menos uno</option></select></div></div></details>
      <details class="sf-grupo"><summary><feather-icon icon="HeartIcon" />Embalsamado<span v-if="f.embalsamado !== ''" class="sf-num">1</span><feather-icon icon="ChevronDownIcon" /></summary><div class="sf-menu"><label v-for="o in embalsamados" :key="o.value"><input type="radio" name="sf-embalsamado" :value="o.value" v-model="f.embalsamado" />{{ o.label }}</label></div></details>
      <details class="sf-grupo sf-traslados"><summary><feather-icon icon="MapPinIcon" />Destino del traslado<span v-if="f.traslados.length" class="sf-num">{{ f.traslados.length }}</span><feather-icon icon="ChevronDownIcon" /></summary><div class="sf-menu"><input v-model="buscarDestino" class="sf-buscar-destino" placeholder="Buscar destino" aria-label="Buscar destino de traslado" /><div class="sf-destinos"><label v-for="d in destinosVisibles" :key="d"><input type="checkbox" :value="d" v-model="f.traslados" />{{ d }}</label><p v-if="!destinosVisibles.length">No hay destinos disponibles.</p></div></div></details>
    </div>
    <div v-if="chips.length" class="sf-chips"><button v-for="chip in chips" :key="chip.id" type="button" @click="quitar(chip)">{{ chip.label }}<feather-icon icon="XIcon" /></button></div>
    <p v-if="f.desde || f.hasta" class="sf-aclaracion">Las fechas corresponden a la contratación. Las solicitudes sin contrato no tienen fecha de contratación.</p>
  </vx-card>
</template>
<script>
import flatPickr from 'vue-flatpickr-component';
import 'flatpickr/dist/flatpickr.css';
import 'flatpickr/dist/themes/airbnb.css';
import { Spanish } from 'flatpickr/dist/l10n/es.js';
/** Card aislada: emite filtros sin consultar API. Los grupos permiten combinar
 * opciones, muestran chips removibles y cierran sus menús al pulsar fuera/Escape. */
const inicial=()=>({numero:'',fallecido:'',cliente:'',desde:'',hasta:'',estado:'',destinos:[],coincidencia:'todos',embalsamado:'',velacion:[],cementerio:[],origen:[],traslados:[]});
export default {
  name:'FiltrosServiciosFunerarios',components:{flatPickr},props:{traslados:{type:Array,default:()=>[]},reporteDeshabilitado:{type:Boolean,default:false}},
  data(){return {f:inicial(),buscarDestino:'',fechas:[{key:'desde',label:'Contratación desde'},{key:'hasta',label:'Contratación hasta'}],calendario:{locale:Spanish,dateFormat:'Y-m-d',altInput:true,altFormat:'j \\d\\e F \\d\\e Y',altInputClass:'sf-fecha-input',disableMobile:true,allowInput:false},
    estados:[{value:'',label:'Todas'},{value:'1',label:'Por pagar'},{value:'2',label:'Pagadas'},{value:'3',label:'Activas'},{value:'4',label:'Sin contrato'},{value:'0',label:'Canceladas'}],embalsamados:[{value:'',label:'Todos'},{value:'1',label:'Embalsamados'},{value:'0',label:'No embalsamados'}],
    grupos:[{key:'destinos',label:'Servicios incluidos',icon:'LayersIcon',options:[{value:'inhumacion',label:'Inhumación'},{value:'cremacion',label:'Cremación'},{value:'traslado',label:'Traslado'},{value:'misa',label:'Ceremonia religiosa'},{value:'aseguradora',label:'Aseguradora'},{value:'custodia',label:'Custodia'}]},
      {key:'velacion',label:'Velación',icon:'HomeIcon',options:[{value:'empresa',label:'En Aeternus'},{value:'otro',label:'En otro lugar'},{value:'sin',label:'Sin velación'}]},
      {key:'cementerio',label:'Inhumación',icon:'MapPinIcon',options:[{value:'aeternus',label:'Cementerio Aeternus'},{value:'otro',label:'Otro cementerio'},{value:'sin',label:'Sin inhumación'}]},
      {key:'origen',label:'Propiedad / plan utilizado',icon:'FileTextIcon',options:[{value:'terreno_futuro',label:'Propiedad de cementerio a futuro'},{value:'terreno_inmediato',label:'Propiedad de cementerio de uso inmediato'},{value:'plan_futuro',label:'Plan funerario a futuro'},{value:'plan_inmediato',label:'Plan funerario de uso inmediato'},{value:'sin',label:'Sin propiedad ni plan vinculado'}]}]};},
  computed:{destinosVisibles(){return this.traslados.filter(x=>x.toLocaleLowerCase('es').includes(this.buscarDestino.toLocaleLowerCase('es')));},chips(){const c=[];['numero','fallecido','cliente','desde','hasta'].forEach(k=>{if(this.f[k])c.push({id:k,key:k,label:({numero:'Servicio',fallecido:'Fallecido',cliente:'Cliente',desde:'Desde',hasta:'Hasta'})[k]+': '+(k==='desde'||k==='hasta'?this.fechaHumana(this.f[k]):this.f[k])});});if(this.f.estado!=='')c.push({id:'estado',key:'estado',label:this.estados.find(x=>x.value===this.f.estado).label});if(this.f.embalsamado!=='')c.push({id:'embalsamado',key:'embalsamado',label:this.embalsamados.find(x=>x.value===this.f.embalsamado).label});this.grupos.forEach(g=>this.f[g.key].forEach(v=>c.push({id:g.key+v,key:g.key,value:v,label:g.options.find(o=>o.value===v).label})));this.f.traslados.forEach(v=>c.push({id:'traslado'+v,key:'traslados',value:v,label:'Traslado: '+v}));return c;}},
  watch:{f:{deep:true,handler(){this.emitir();}}},
  methods:{emitir(){this.$emit('change',JSON.parse(JSON.stringify(this.f)));},limpiar(){this.f=inicial();this.buscarDestino='';this.cerrarMenus();},quitar(c){if(Array.isArray(this.f[c.key]))this.f[c.key]=this.f[c.key].filter(v=>v!==c.value);else this.f[c.key]='';},fechaHumana(v){const partes=v.split('-').map(Number);return new Date(partes[0],partes[1]-1,partes[2]).toLocaleDateString('es-MX',{day:'numeric',month:'long',year:'numeric'});},cerrarMenus(e){this.$el.querySelectorAll('details[open]').forEach(d=>{if(!e||!d.contains(e.target))d.removeAttribute('open');});},tecla(e){if(e.key==='Escape')this.cerrarMenus();}},
  mounted(){document.addEventListener('click',this.cerrarMenus);document.addEventListener('keydown',this.tecla);},beforeDestroy(){document.removeEventListener('click',this.cerrarMenus);document.removeEventListener('keydown',this.tecla);}
};
</script>
<style scoped>
.sf-campos{display:grid;grid-template-columns:minmax(120px,.7fr) repeat(2,minmax(170px,1.4fr)) repeat(2,minmax(160px,1fr));gap:16px}.sf-campos>div{min-width:0}.sf-campos label{display:block;font:11px Arial,sans-serif;color:#757575;text-transform:uppercase;margin-bottom:7px}.sf-campos input,.sf-menu select,.sf-buscar-destino{width:100%;height:38px;box-sizing:border-box;border:1px solid #c7c7c7;border-radius:0;padding:0 10px;background:white;color:#626970;font:13px Arial,sans-serif}.sf-campos input:focus{outline:none;border-color:#ab891d}.sf-fecha{position:relative}.sf-fecha >>> input{width:100%!important;height:38px!important;border:1px solid #c7c7c7!important;border-radius:0!important;padding:0 32px 0 10px!important;box-sizing:border-box;font:13px Arial,sans-serif;background:white}.sf-fecha button{position:absolute;right:6px;top:8px;border:0;background:white;color:#888;padding:3px;cursor:pointer}.sf-fecha button >>> svg{width:14px;height:14px}.sf-botones{display:flex;gap:8px;flex-wrap:wrap;margin-top:17px}.sf-grupo{position:relative;flex:1 1 145px;min-width:0}.sf-grupo summary{justify-content:space-between}.sf-grupo summary .sf-num{margin-left:auto}.sf-grupo summary{list-style:none;display:flex;align-items:center;gap:8px;border:1px solid #d2d2d2;min-height:36px;padding:0 11px;background:white;color:#666;cursor:pointer;font:13px Arial,sans-serif}.sf-grupo summary::-webkit-details-marker{display:none}.sf-grupo summary >>> svg{width:15px;height:15px}.sf-grupo[open] summary{border-color:#ab891d;color:#92731b;background:#faf8f0}.sf-num{border-radius:10px;padding:1px 5px;font-size:10px;background:#f0e7c7;color:#96751b}.sf-menu{position:absolute;z-index:1000;top:calc(100% + 5px);left:0;width:280px;max-width:calc(100vw - 50px);padding:10px;background:white;box-shadow:0 4px 15px #0002;border:1px solid #ddd;box-sizing:border-box}.sf-menu>label,.sf-destinos>label{display:flex;gap:9px;align-items:center;padding:8px;line-height:1.4;font-size:12px;cursor:pointer}.sf-menu input[type=checkbox],.sf-menu input[type=radio]{accent-color:#a58828;flex-shrink:0}.sf-coincidencia{border-top:1px solid #eee;margin-top:7px;padding-top:9px}.sf-coincidencia label{font-size:11px;margin-bottom:5px;display:block;color:#777}.sf-destinos{max-height:220px;overflow-y:auto;margin-top:5px}.sf-destinos p{padding:10px;color:#888;font-size:12px}.sf-chips{display:flex;flex-wrap:wrap;gap:7px;margin-top:14px;padding-top:12px;border-top:1px solid #eee}.sf-chips button{border:0;background:#eee;color:#666;padding:5px 8px;display:flex;gap:8px;align-items:center;font:11px Arial,sans-serif;cursor:pointer}.sf-chips >>> svg{width:12px;height:12px}.sf-limpiar{display:inline-flex;align-items:center;gap:6px;background:transparent;border:0;color:#888;font:12px Arial,sans-serif;cursor:pointer}.sf-limpiar >>> svg{width:14px;height:14px}.sf-aclaracion{color:#888;font-size:11px;margin-top:10px}.servicios-filtros-card >>> .vx-card__collapsible-content{overflow:visible!important}
@media(max-width:1400px){.sf-campos{grid-template-columns:repeat(6,minmax(0,1fr))}.sf-campos>div{grid-column:span 2}.sf-campos>div:nth-child(n+4){grid-column:span 3}}
@media(max-width:700px){.sf-campos{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.sf-campos>div,.sf-campos>div:nth-child(n+4){grid-column:span 1}.sf-campos>div:nth-child(3){grid-column:span 2}.sf-menu{position:fixed;top:30%;left:20px;right:20px;width:auto;max-width:none;max-height:60vh;overflow-y:auto}.sf-campos input,.sf-fecha >>> input{font-size:16px!important}}
@media(max-width:400px){.sf-campos{display:flex;flex-direction:column}}
.sf-reporte{display:inline-flex;align-items:center;gap:6px;margin-right:18px;border:0;background:transparent;color:#96751f;font:600 12px Arial,sans-serif;cursor:pointer;padding:4px 0}.sf-reporte >>> svg{width:14px;height:14px}.sf-reporte:hover{text-decoration:underline}.sf-reporte:disabled{opacity:.5;cursor:default}.servicios-filtros-card >>> .vx-card__actions{display:flex;align-items:center;flex-wrap:wrap;gap:8px}
@media(max-width:700px){.sf-grupo{flex-basis:calc(50% - 8px)}.sf-reporte{margin-right:6px}.servicios-filtros-card >>> .vx-card__header{flex-wrap:wrap;gap:12px}}
</style>
